    sfx, wh = np.zeros((N, 2)), np.zeros((N, 2))
    for e in spine['events']:
        k, t = e['kind'], e['t']
        out = wh if split and is_whoosh(k, spine) else sfx
        add = _add if real is None or not real.wants(e) else (lambda buf, tt, sig, pan=0.0, g=1.0, _e=e: _add(buf, tt, real.sound(_e, sig * g), pan))
        if k == 'riser':
            d = e['to'] - t; add(out, t, mixs(noise_sweep(d, 400, 3500, 0.10, att=d * 0.8), glide(57, 62, d, 0.05)))
        elif k == 'whoosh_air':                      # đẩy chậm (máy quay "thở"): gió rất nhẹ, dải hẹp, không cao độ
            d = e.get('dur', 2.0); add(out, t, e.get('gain', 1.0) * noise_sweep(d, 900, 1400, 0.035, att=d * 0.5))
        elif k == 'whoosh_soft':
            add(out, t, e.get('gain', 1.0) * noise_sweep(e.get('dur', 0.9), 2500, 500, 0.10, 0.2))
        elif k == 'tick':
            add(out, t, mixs(s2_tick(e['v']), 0.4 * s2_pulse(hz(qpenta(62 + 8 * e['v'])), e['v'] * 0.6)), rng.uniform(-0.6, 0.6))
        elif k == 'gather':
            add(out, t, pad([hz(62), hz(69), hz(74)], 1.6, 0.25, 1800))
        elif k == 'thud':
            add(out, t, felt(hz(31), 0.12))   # v3e: chỉ còn nốt trầm mềm (lượt đạo diễn v3d: thud gắt)   # lượt đạo diễn v3c: thud vẫn ngang lời → thêm −6 dB
        elif k == 'drone_on':
            d = e['until'] - t; n = int(d * SR); tt = np.arange(n) / SR
            x = (np.sin(2 * np.pi * 73.4 * tt) + 0.3 * np.sin(2 * np.pi * 146.8 * tt)) * (1 + 0.15 * np.sin(2 * np.pi * 0.3 * tt))
            add(out, t, x * np.minimum(1, tt / 0.8) * np.minimum(1, (d - tt) / 0.8) * 0.024)
        elif k == 'slide_down':
            add(out, t, mixs(glide(74, 62, e['dur'], 0.12), noise_sweep(e['dur'], 3000, 700, 0.05, 0.4)))
        elif k == 'chime':
            add(out, t, lp1(bell(hz(74), 0.28), 2500), 0.15); add(out, t + 0.09, lp1(bell(hz(81), 0.14), 2500), -0.15)   # v3f: chime dịu (bớt bội 4–7 kHz)
        elif k == 'swish':
            d = e['to'] - t; add(out, t, mixs(noise_sweep(d, 900, 5000, 0.12, att=d * 0.7), glide(62, 74, d, 0.06)))
        elif k == 'impact':
            add(out, t, mixs(felt(hz(26), 0.32, 1.6), thump(0.32))); add(out, t, bell(hz(74), 0.06), 0.0)   # −10 dB, sau chữ 'cap'
        elif k == 'rise':
            add(out, t, glide(57, 69, e['dur'], 0.10))
        elif k in ('whoosh_mode', 'whoosh_push'):   # chuyển chế độ / đẩy máy (quy tắc 3): gió có cao độ, cùng khoá
            d = e['dur']; lo, hi = (500, 4200) if k == 'whoosh_mode' else (700, 2600); gn = e.get('gain', 1.0)
            add(out, t, gn * mixs(noise_sweep(d, lo, hi, 0.13 if k == 'whoosh_mode' else 0.09, att=d * 0.6), glide(62, 69, d, 0.05)))
        elif k == 'land':                            # chạm khi tới tư thế mới (S2: tick + nhịp trầm)
            add(out, t, mixs(s2_tick(0.35), 0.6 * s2_pulse(hz(50), 0.38 if e.get('mode') else 0.3)))   # E5a: tiếng chạm đổi chế độ to nhất → hạ
    return (sfx, wh) if split else sfx


def room_tone(N, venv, mus_env):
    """Sàn room tone (≈ −62 dBFS); +6 dB trong khoảng lặng (không lời, nhạc nhỏ) — G-003."""
    x = rng.standard_normal(N)
    b, a = signal.butter(1, 900, 'low', fs=SR)
    x = signal.lfilter(b, a, x); x = x / np.sqrt(np.mean(x ** 2)) * 10 ** (-62 / 20)
    quiet = ((venv < 1e-3) & (mus_env < 10 ** (-40 / 20))).astype(float)
    q = np.repeat(quiet, SR // 200)[:N]; q = np.pad(q, (0, N - len(q)))
    g = 10 ** (6 * uniform_filter1d(q, int(0.2 * SR)) / 20)
    return np.stack([x * g, np.roll(x, 2400) * g], 1)


def silence_gain(N, windows, ramp=0.05):
    """Hệ số (N,) = 0 trong mọi cửa sổ [a, b] (giây), 1 ngoài cửa sổ, cos `ramp` s ngay ngoài hai đầu; None nếu không có cửa sổ."""
    if not windows:
        return None
    t = np.arange(N) / SR
    g = np.ones(N)
    for a, b in windows:
        d = np.maximum(a - t, t - b)          # > 0 ngoài cửa sổ: khoảng cách tới cửa sổ
        w = np.where(d <= 0, 0.0, np.where(d >= ramp, 1.0, 0.5 - 0.5 * np.cos(np.pi * np.clip(d, 0, ramp) / ramp)))
        g = np.minimum(g, w)
    return g


def env200(x):
    m = np.abs(x if x.ndim == 1 else x.mean(1))
    k = SR // 200
    return maximum_filter1d(m[:len(m) // k * k].reshape(-1, k).max(1), 3)


def duck(layer, venv, depth_db=8.0, carve=True):
    """Side-chain theo lời + mất dải 1–4 kHz khi có lời (G-006)."""
    act = (venv > 10 ** (-38 / 20)).astype(float)
    a = np.repeat(uniform_filter1d(act, 10), SR // 200)[:len(layer)]
    a = np.pad(a, (0, len(layer) - len(a)))
    g = 10 ** (-depth_db * a / 20)
    y = layer * g[:, None]
    if carve:
        band = signal.sosfiltfilt(signal.butter(2, [1000, 4000], 'band', fs=SR, output='sos'), y, axis=0)
        y = y - band * a[:, None] * 0.9
    return y


def rms_active(x, venv):
    act = np.repeat((venv > 10 ** (-38 / 20)), SR // 200)[:len(x)]
    act = np.pad(act, (0, len(x) - len(act)))
    m = x if x.ndim == 1 else x.mean(1)
    return np.sqrt(np.mean(m[act.astype(bool)] ** 2) + 1e-12)


